<?php require_once __DIR__.'/../config/db.php';$pageTitle='Subjects';require __DIR__.'/includes/admin_layout_start.php';$errors=[];$edit=null;$pdo=null;try{$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){if(!verify_csrf($_POST['csrf_token']??null))$errors[]='Your session expired.';else{$action=$_POST['action']??'';$id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);$name=trim((string)($_POST['name']??''));$icon=trim((string)($_POST['icon']??''));if(in_array($action,['create','update'],true)&&(mb_strlen($name)<2||mb_strlen($name)>100))$errors[]='Subject name must be 2–100 characters.';if(!$errors){if($action==='create'){$s=$pdo->prepare('INSERT INTO subjects (name,icon) VALUES (:name,:icon)');$s->execute(['name'=>$name,'icon'=>$icon?:null]);$msg='Subject added.';}elseif($action==='update'&&$id){$s=$pdo->prepare('UPDATE subjects SET name=:name,icon=:icon WHERE id=:id');$s->execute(['name'=>$name,'icon'=>$icon?:null,'id'=>$id]);$msg='Subject updated.';}elseif($action==='delete'&&$id){$s=$pdo->prepare('DELETE FROM subjects WHERE id=:id');$s->execute(['id'=>$id]);$msg='Subject deleted.';}else throw new InvalidArgumentException('Invalid subject action.');flash('admin_success',$msg);header('Location: subjects.php');exit;}}}if(isset($_GET['edit'])&&filter_var($_GET['edit'],FILTER_VALIDATE_INT)){$s=$pdo->prepare('SELECT id,name,icon FROM subjects WHERE id=:id');$s->execute(['id'=>(int)$_GET['edit']]);$edit=$s->fetch();}$subjects=$pdo->query('SELECT id,name,icon,created_at FROM subjects ORDER BY name')->fetchAll();}catch(PDOException $e){$errors[]='That subject already exists or the database is unavailable.';$subjects=[];}catch(Throwable $e){$errors[]='Unable to update subjects.';$subjects=[];} ?>
<div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h3 mb-1">Subjects</h1><p class="text-secondary mb-0">These appear in the public Popular Subjects section.</p></div><button class="btn btn-brand" data-bs-toggle="modal" data-bs-target="#subjectModal">Add subject</button></div><?php if($m=flash('admin_success')):?><div class="alert alert-success"><?=e($m)?></div><?php endif;?><?php if($errors):?><div class="alert alert-danger"><?=e($errors[0])?></div><?php endif;?><div class="admin-table table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Icon</th><th>Name</th><th>Created</th><th class="text-end">Actions</th></tr></thead><tbody><?php foreach($subjects as $s):?><tr><td><?=e($s['icon']?:'—')?></td><td class="fw-semibold"><?=e($s['name'])?></td><td><?=e(date('d M Y',strtotime($s['created_at'])))?></td><td class="text-end"><a class="btn btn-sm btn-outline-brand" href="subjects.php?edit=<?=e((string)$s['id'])?>">Edit</a><form class="d-inline" method="post" onsubmit="return confirm('Delete this subject?')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=e((string)$s['id'])?>"><button class="btn btn-sm btn-outline-danger">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div><div class="modal fade <?= $edit?'show d-block':'' ?>" id="subjectModal" tabindex="-1" <?= $edit?'style="background:rgba(0,0,0,.4)"':''?>><div class="modal-dialog"><form class="modal-content" method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="<?= $edit?'update':'create'?>"><?php if($edit):?><input type="hidden" name="id" value="<?=e((string)$edit['id'])?>"><?php endif;?><div class="modal-header"><h5 class="modal-title"><?= $edit?'Edit':'Add'?> subject</h5><a href="subjects.php" class="btn-close"></a></div><div class="modal-body"><label class="form-label">Subject name</label><input class="form-control mb-3" name="name" value="<?=e($edit['name']??'')?>" required maxlength="100"><label class="form-label">Icon or image reference <small class="text-secondary">(optional)</small></label><input class="form-control" name="icon" value="<?=e($edit['icon']??'')?>" maxlength="255"></div><div class="modal-footer"><a href="subjects.php" class="btn btn-light">Cancel</a><button class="btn btn-brand">Save subject</button></div></form></div></div><?php if($edit):?><script>new bootstrap.Modal(document.getElementById('subjectModal')).show()</script><?php endif;?><?php require __DIR__.'/includes/admin_layout_end.php'; ?>
